#include <bits/stdc++.h>

using namespace std;

auto containsNearbyDuplicate(vector<int> &nums, int k) -> bool {
    int n = nums.size();
    unordered_set<int> st;
    for(int i = 0; i < n; i++) {
        auto it = st.find(nums[i]);
        if(it != st.end()) return abs(it->second, i);
        else st.insert(nums[i]);
    }
    return false;
}

